create type public.app_role as enum ('customer','delivery_boy','cashier','picker','store_manager','inventory_manager','accountant','super_admin');
create type public.order_status as enum ('placed','accepted','picking','packed','out_for_delivery','delivered','cancelled','returned','refunded');
create table if not exists public.roles (id bigint generated by default as identity primary key, name public.app_role unique not null);
create table if not exists public.users (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role_id bigint references public.roles(id), created_at timestamptz not null default now());
create table if not exists public.addresses (id bigint generated by default as identity primary key, user_id uuid not null references public.users(id) on delete cascade, label text not null, line1 text not null, city text not null, postal_code text not null, latitude numeric, longitude numeric, delivery_instructions text);
create table if not exists public.categories (id bigint generated by default as identity primary key, parent_id bigint references public.categories(id) on delete set null, name text not null, slug text unique not null);
create table if not exists public.brands (id bigint generated by default as identity primary key, name text unique not null, slug text unique not null);
create table if not exists public.products (id bigint generated by default as identity primary key, name text not null, slug text unique, sku text unique, barcode text unique, brand_id bigint references public.brands(id), category_id bigint references public.categories(id), product_type text not null default 'simple', description text, ingredients text, nutrition jsonb not null default '{}'::jsonb, attributes jsonb not null default '{}'::jsonb, weight numeric, is_organic boolean not null default false, is_vegetarian boolean not null default false, is_gluten_free boolean not null default false, country_of_origin text, mrp numeric(12,2) not null default 0, selling_price numeric(12,2) not null default 0, gst numeric(5,2) not null default 0, hsn text, rating numeric(2,1) not null default 0, review_count integer not null default 0, search_vector tsvector generated always as (to_tsvector('simple', coalesce(name,'') || ' ' || coalesce(description,''))) stored, created_at timestamptz not null default now());
create table if not exists public.product_images (id bigint generated by default as identity primary key, product_id bigint not null references public.products(id) on delete cascade, storage_path text not null, alt_text text, sort_order integer not null default 0);
create table if not exists public.product_variants (id bigint generated by default as identity primary key, product_id bigint not null references public.products(id) on delete cascade, name text not null, sku text unique, price numeric(12,2) not null, weight numeric, stock integer not null default 0);
create table if not exists public.product_attributes (id bigint generated by default as identity primary key, name text unique not null);
create table if not exists public.product_attribute_values (id bigint generated by default as identity primary key, product_id bigint not null references public.products(id) on delete cascade, attribute_id bigint not null references public.product_attributes(id) on delete cascade, value text not null);
create table if not exists public.inventory (product_id bigint primary key references public.products(id) on delete cascade, current_stock integer not null default 0, reserved_stock integer not null default 0, warehouse_stock integer not null default 0, reorder_level integer not null default 0);
create table if not exists public.inventory_batches (id bigint generated by default as identity primary key, product_id bigint not null references public.products(id) on delete cascade, batch_number text not null, expiry_date date, quantity integer not null default 0);
create table if not exists public.suppliers (id bigint generated by default as identity primary key, name text not null, phone text, email text);
create table if not exists public.purchase_orders (id bigint generated by default as identity primary key, supplier_id bigint references public.suppliers(id), status text not null default 'draft', created_at timestamptz not null default now());
create table if not exists public.purchase_items (id bigint generated by default as identity primary key, purchase_order_id bigint not null references public.purchase_orders(id) on delete cascade, product_id bigint not null references public.products(id), quantity integer not null, unit_cost numeric(12,2) not null);
create table if not exists public.orders (id bigint generated by default as identity primary key, user_id uuid references public.users(id), status public.order_status not null default 'placed', address_id bigint references public.addresses(id), delivery_slot text, total numeric(12,2) not null default 0, created_at timestamptz not null default now());
create table if not exists public.order_items (id bigint generated by default as identity primary key, order_id bigint not null references public.orders(id) on delete cascade, product_id bigint not null references public.products(id), variant_id bigint references public.product_variants(id), quantity integer not null check (quantity > 0), unit_price numeric(12,2) not null, substitute_if_unavailable boolean not null default false);
create table if not exists public.payments (id bigint generated by default as identity primary key, order_id bigint not null references public.orders(id) on delete cascade, method text not null, status text not null default 'pending', amount numeric(12,2) not null);
create table if not exists public.refunds (id bigint generated by default as identity primary key, order_id bigint not null references public.orders(id), amount numeric(12,2) not null, reason text, created_at timestamptz not null default now());
create table if not exists public.coupons (id bigint generated by default as identity primary key, code text unique not null, kind text not null, value numeric(12,2) not null, starts_at timestamptz, ends_at timestamptz, category_id bigint references public.categories(id), brand_id bigint references public.brands(id), active boolean not null default true);
create table if not exists public.wishlists (user_id uuid references public.users(id) on delete cascade, product_id bigint references public.products(id) on delete cascade, primary key(user_id, product_id));
create table if not exists public.cart (user_id uuid references public.users(id) on delete cascade, session_id text, product_id bigint references public.products(id), variant text, quantity integer not null check (quantity > 0), created_at timestamptz not null default now(), primary key(user_id, product_id, variant));
create table if not exists public.reviews (id bigint generated by default as identity primary key, user_id uuid references public.users(id), product_id bigint references public.products(id) on delete cascade, rating integer check (rating between 1 and 5), body text, created_at timestamptz not null default now());
create table if not exists public.delivery_slots (id bigint generated by default as identity primary key, starts_at timestamptz not null, ends_at timestamptz not null, capacity integer not null);
create table if not exists public.delivery_staff (user_id uuid primary key references public.users(id) on delete cascade, vehicle_number text, active boolean not null default true);
create table if not exists public.notifications (id bigint generated by default as identity primary key, user_id uuid references public.users(id) on delete cascade, title text not null, body text not null, read_at timestamptz);
create table if not exists public.wallet_transactions (id bigint generated by default as identity primary key, user_id uuid references public.users(id) on delete cascade, amount numeric(12,2) not null, reason text not null, created_at timestamptz not null default now());
create table if not exists public.reward_points (user_id uuid primary key references public.users(id) on delete cascade, balance integer not null default 0);
create table if not exists public.audit_logs (id bigint generated by default as identity primary key, actor_id uuid references auth.users(id), action text not null, table_name text not null, row_id text, payload jsonb, created_at timestamptz not null default now());
create index if not exists products_search_idx on public.products using gin(search_vector);
create index if not exists products_category_idx on public.products(category_id);
create index if not exists orders_status_idx on public.orders(status, created_at desc);
create index if not exists inventory_low_stock_idx on public.inventory(current_stock, reorder_level);
alter table public.users enable row level security; alter table public.addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.cart enable row level security; alter table public.wishlists enable row level security; alter table public.reviews enable row level security; alter table public.notifications enable row level security; alter table public.wallet_transactions enable row level security; alter table public.reward_points enable row level security; alter table public.audit_logs enable row level security; alter table public.products enable row level security;
create policy "catalog is public" on public.products for select using (true);
create policy "own addresses" on public.addresses for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own orders" on public.orders for select using (user_id = auth.uid());
create policy "own order items" on public.order_items for select using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));
create policy "own cart" on public.cart for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create or replace function public.has_role(required_role public.app_role) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.users u join public.roles r on r.id = u.role_id where u.id = auth.uid() and (r.name = required_role or r.name = 'super_admin')); $$;
alter table public.roles enable row level security; alter table public.inventory enable row level security;
create policy "staff can read inventory" on public.inventory for select using (public.has_role('inventory_manager') or public.has_role('store_manager'));
create policy "staff can manage inventory" on public.inventory for all using (public.has_role('inventory_manager') or public.has_role('store_manager')) with check (public.has_role('inventory_manager') or public.has_role('store_manager'));
create policy "staff can read orders" on public.orders for select using (user_id = auth.uid() or public.has_role('store_manager') or public.has_role('accountant') or public.has_role('picker'));
create policy "own wishlist" on public.wishlists for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own reviews" on public.reviews for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own notifications" on public.notifications for select using (user_id = auth.uid());
create policy "own wallet" on public.wallet_transactions for select using (user_id = auth.uid());
create policy "own rewards" on public.reward_points for select using (user_id = auth.uid());
create or replace function public.place_order(p_user_id uuid, p_address_id bigint, p_items jsonb, p_total numeric, p_payment_method text) returns bigint language plpgsql security definer as $$ declare new_order bigint; item jsonb; begin insert into public.orders(user_id,address_id,total) values(p_user_id,p_address_id,p_total) returning id into new_order; for item in select * from jsonb_array_elements(p_items) loop insert into public.order_items(order_id,product_id,quantity,unit_price,substitute_if_unavailable) values(new_order,(item->>'product_id')::bigint,(item->>'quantity')::integer,(item->>'unit_price')::numeric,coalesce((item->>'substitute')::boolean,false)); update public.inventory set current_stock = current_stock - (item->>'quantity')::integer where product_id=(item->>'product_id')::bigint and current_stock >= (item->>'quantity')::integer; if not found then raise exception 'Insufficient stock'; end if; end loop; insert into public.payments(order_id,method,amount) values(new_order,p_payment_method,p_total); return new_order; end; $$;
